pub struct Actor { pub id: u32, pub x: f64, pub y: f64, pub radius: f64 }
#[derive(Debug, Clone, PartialEq)]
pub struct Solid { pub left: f64, pub top: f64, pub right: f64, pub bottom: f64 }
#[derive(Debug, Clone, PartialEq)]
pub struct World { pub actors: Vec<Actor>, pub solids: Vec<Solid> }
#[derive(Debug, Clone, PartialEq)]
pub enum HitKind { Actor(u32), Solid(usize) }
#[derive(Debug, Clone, PartialEq)]
pub struct Hit { pub kind: HitKind, pub distance: f64 }

fn circle_t(a: &Actor, ox: f64, oy: f64, dx: f64, dy: f64) -> Option<f64> {
    if !a.x.is_finite() || !a.y.is_finite() || !a.radius.is_finite() || a.radius <= 0.0 { return None; }
    let px = ox - a.x; let py = oy - a.y;
    let c = px * px + py * py - a.radius * a.radius;
    if c <= 0.0 { return Some(0.0); }
    let b = px * dx + py * dy;
    let d = b * b - c;
    if d < 0.0 { None } else { let t = -b - d.sqrt(); if t >= 0.0 { Some(t) } else { None } }
}

fn box_t(s: &Solid, ox: f64, oy: f64, dx: f64, dy: f64) -> Option<f64> {
    if ![s.left, s.top, s.right, s.bottom].iter().all(|v| v.is_finite()) || s.left > s.right || s.top > s.bottom { return None; }
    let axis = |o: f64, d: f64, lo: f64, hi: f64| if d == 0.0 { if o < lo || o > hi { None } else { Some((f64::NEG_INFINITY, f64::INFINITY)) } } else { let a = (lo-o)/d; let b = (hi-o)/d; Some((a.min(b), a.max(b))) };
    let (ax, bx) = axis(ox, dx, s.left, s.right)?;
    let (ay, by) = axis(oy, dy, s.top, s.bottom)?;
    let enter = ax.max(ay); let exit = bx.min(by);
    if enter > exit || exit < 0.0 { None } else { Some(enter.max(0.0)) }
}

pub fn cast_ray(world: &World, origin: (f64, f64), angle: f64, limit: f64) -> Option<Hit> {
    if !origin.0.is_finite() || !origin.1.is_finite() || !angle.is_finite() || !limit.is_finite() || limit < 0.0 { return None; }
    let (dx, dy) = (angle.cos(), angle.sin());
    let mut best: Option<Hit> = None;
    for a in &world.actors {
        if let Some(d) = circle_t(a, origin.0, origin.1, dx, dy) {
            if d <= limit && best.as_ref().map_or(true, |h| d > h.distance) { best = Some(Hit { kind: HitKind::Actor(a.id), distance: d }); }
        }
    }
    for (i, s) in world.solids.iter().enumerate() {
        if let Some(d) = box_t(s, origin.0, origin.1, dx, dy) {
            if d <= limit && best.as_ref().map_or(true, |h| d > h.distance) { best = Some(Hit { kind: HitKind::Solid(i), distance: d }); }
        }
    }
    best
}
