#[path = "solution.rs"]
mod solution;

use solution::{cast_ray, Actor, Hit, HitKind, Solid, World};
use std::f64::consts::PI;

fn assert_hit(actual: Option<Hit>, kind: HitKind, distance: f64) {
    let hit = actual.expect("expected a hit");
    assert_eq!(hit.kind, kind);
    assert!((hit.distance - distance).abs() < 1e-10, "distance was {}", hit.distance);
}

#[test]
fn chooses_closest_hit_and_respects_inclusive_limit() {
    let world = World {
        actors: vec![Actor { id: 1, x: 8.0, y: 0.0, radius: 1.0 }],
        solids: vec![Solid { left: 4.0, top: -1.0, right: 5.0, bottom: 1.0 }],
    };
    assert_hit(cast_ray(&world, (0.0, 0.0), 0.0, 10.0), HitKind::Solid(0), 4.0);
    assert_hit(cast_ray(&world, (0.0, 0.0), 0.0, 4.0), HitKind::Solid(0), 4.0);
    assert_eq!(cast_ray(&world, (0.0, 0.0), 0.0, 3.999), None);
}

#[test]
fn inside_hits_at_zero_and_actor_wins_cross_kind_tie() {
    let inside = World {
        actors: vec![],
        solids: vec![Solid { left: -1.0, top: -1.0, right: 1.0, bottom: 1.0 }],
    };
    assert_hit(cast_ray(&inside, (0.0, 0.0), PI / 3.0, 0.0), HitKind::Solid(0), 0.0);

    let tied = World {
        actors: vec![Actor { id: 9, x: 5.0, y: 0.0, radius: 1.0 }],
        solids: vec![Solid { left: 4.0, top: -2.0, right: 6.0, bottom: 2.0 }],
    };
    assert_hit(cast_ray(&tied, (0.0, 0.0), 0.0, 4.0), HitKind::Actor(9), 4.0);
}

#[test]
fn slice_order_breaks_same_kind_ties() {
    let actors = World {
        actors: vec![
            Actor { id: 10, x: 5.0, y: 0.0, radius: 1.0 },
            Actor { id: 11, x: 5.0, y: 0.0, radius: 1.0 },
        ],
        solids: vec![],
    };
    assert_hit(cast_ray(&actors, (0.0, 0.0), 0.0, 20.0), HitKind::Actor(10), 4.0);

    let solids = World {
        actors: vec![],
        solids: vec![
            Solid { left: 3.0, top: -1.0, right: 4.0, bottom: 1.0 },
            Solid { left: 3.0, top: -2.0, right: 5.0, bottom: 2.0 },
        ],
    };
    assert_hit(cast_ray(&solids, (0.0, 0.0), 0.0, 20.0), HitKind::Solid(0), 3.0);
}

#[test]
fn invalid_inputs_and_malformed_entries_are_ignored() {
    let world = World {
        actors: vec![
            Actor { id: 1, x: 2.0, y: 0.0, radius: 0.0 },
            Actor { id: 2, x: f64::NAN, y: 0.0, radius: 1.0 },
            Actor { id: 3, x: 3.0, y: 0.0, radius: 1.0 },
        ],
        solids: vec![
            Solid { left: 5.0, top: 1.0, right: 4.0, bottom: 0.0 },
            Solid { left: f64::NEG_INFINITY, top: 0.0, right: 1.0, bottom: 1.0 },
        ],
    };
    assert_hit(cast_ray(&world, (0.0, 0.0), 0.0, 10.0), HitKind::Actor(3), 2.0);
    assert_eq!(cast_ray(&world, (f64::NAN, 0.0), 0.0, 10.0), None);
    assert_eq!(cast_ray(&world, (0.0, f64::INFINITY), 0.0, 10.0), None);
    assert_eq!(cast_ray(&world, (0.0, 0.0), f64::NAN, 10.0), None);
    assert_eq!(cast_ray(&world, (0.0, 0.0), 0.0, -1.0), None);
    assert_eq!(cast_ray(&world, (0.0, 0.0), 0.0, f64::INFINITY), None);
}

#[test]
fn ray_direction_and_world_non_mutation() {
    let world = World {
        actors: vec![Actor { id: 4, x: -4.0, y: 0.0, radius: 1.0 }],
        solids: vec![],
    };
    let original = world.clone();
    assert_hit(cast_ray(&world, (0.0, 0.0), PI, 10.0), HitKind::Actor(4), 3.0);
    assert_eq!(world, original);
}

